import { operation, resource, tag } from "@tinker/core";
import type { Operation } from "@tinker/core";

import { applyBootstrap, syncClient } from "~/components/sync/client/sync";
import { tabStop } from "~/components/sync/client/tab";
import type { Sync } from "~/components/sync/envelopes";
import { snapshotSource } from "~/components/sync/functions";
import type { Stream } from "~/components/sync/protocol";
import { streamMessageSlot } from "~/components/sync/slots";

/** One account version owns one in-flight network load and its applied snapshot. */
const snapshotCache = resource({
  label: "sync.snapshotCache",
  depends: { sync: syncClient, apply: applyBootstrap, source: snapshotSource },
  factory: ({ sync, apply, source }) => {
    let loadedVersion = -1;
    let loading: { version: number; promise: Promise<Sync.Snapshot> } | undefined;
    return {
      async read(signal: AbortSignal) {
        const token = sync.capture();
        if (loadedVersion === token.version) return sync.snapshot();
        if (loading?.version === token.version) return loading.promise;

        const request = {
          version: token.version,
          promise: source.load({ signal }).then((snapshot) => {
            const version = apply.run({ rawInput: { snapshot, version: token.version } });
            if (version !== undefined) loadedVersion = version;
            return sync.snapshot();
          }),
        };
        loading = request;
        try {
          return await request.promise;
        } finally {
          if (loading === request) loading = undefined;
        }
      },
    };
  },
});

/** An account change holds ordinary loads until its own snapshot has applied. */
export const snapshotLoader = resource({
  label: "sync.snapshotLoader",
  depends: { sync: syncClient, source: snapshotSource, cache: snapshotCache },
  factory: ({ sync, source, cache }) => {
    let changing: ReturnType<typeof Promise.withResolvers<void>> | undefined;
    return {
      beginAccountChange() {
        changing = Promise.withResolvers<void>();
        return changing;
      },
      endAccountChange(change: ReturnType<typeof Promise.withResolvers<void>>) {
        if (changing === change) changing = undefined;
        change.resolve();
      },
      async completeAccountChange(
        signal: AbortSignal,
        change: ReturnType<typeof Promise.withResolvers<void>>,
      ) {
        try {
          return await cache.read(signal);
        } finally {
          if (changing === change) changing = undefined;
          change.resolve();
        }
      },
      async ready() {
        if (changing) await changing.promise;
      },
      async account(signal: AbortSignal) {
        if (changing) await changing.promise;
        const accountId = await source.account({ signal });
        if (accountId !== sync.cursors().accountId) sync.leave();
        return accountId;
      },
      async load(signal: AbortSignal) {
        if (changing) await changing.promise;
        return cache.read(signal);
      },
    };
  },
});

export const loadSnapshot = operation({
  label: "sync.load",
  depends: { snapshots: snapshotLoader },
  run: ({ snapshots }, { signal }) => snapshots.load(signal),
});

export const checkAccount = operation({
  label: "sync.checkAccount",
  depends: { snapshots: snapshotLoader },
  run: ({ snapshots }, { signal }) => snapshots.account(signal),
});

/** What the tab's stream needs from an EventSource. */
type Source = {
  addEventListener(type: string, listener: (event: MessageEvent<string>) => void): void;
  close(): void;
};

/** How a tab opens its stream: the native EventSource. Scope tests bind a fake. */
export const eventSourceBackend = tag<(url: string) => Source>({
  label: "sync.eventSourceBackend",
});

/**
 * One stream connection at a time. EventSource keeps the framing; frames queue until read, and
 * a ninth unread frame closes the connection, so the tab replays instead of lagging.
 */
export const eventSource = resource({
  label: "sync.eventSource",
  depends: { open: eventSourceBackend.optional },
  factory: ({ open }, { defer }) => {
    let close: (() => void) | undefined;
    defer(() => close?.());

    const queue: string[] = [];
    let ended = true;
    let waiting: ReturnType<typeof Promise.withResolvers<void>> | undefined;

    return {
      connect(cursor: Stream.Cursor, signal: AbortSignal) {
        close?.();
        const url = `/api/sync?cursor=${encodeURIComponent(JSON.stringify(cursor))}`;
        const connection = open.present ? open.value(url) : new EventSource(url);
        ended = false;

        const closeConnection = () => {
          if (ended) return;

          ended = true;
          connection.close();
          queue.length = 0;
          signal.removeEventListener("abort", closeConnection);
          waiting?.resolve();
        };
        close = closeConnection;

        const receive = (event: MessageEvent<string>) => {
          if (ended) return;
          if (queue.length >= 8) {
            closeConnection();
            return;
          }
          queue.push(event.data);
          waiting?.resolve();
        };

        connection.addEventListener("changes", receive);
        connection.addEventListener("account", receive);
        connection.addEventListener("error", closeConnection);
        signal.addEventListener("abort", closeConnection, { once: true });
        if (signal.aborted) closeConnection();
      },
      close() {
        close?.();
      },
      async next() {
        while (!ended && queue.length === 0) {
          const received = Promise.withResolvers<void>();
          waiting = received;
          await received.promise;
          waiting = undefined;
        }
        return ended ? undefined : queue.shift();
      },
    };
  },
});

/** One frame: changes apply (false); an account change leaves the account (true). */
export const receiveMessage = operation({
  label: "sync.receive",
  depends: { sync: syncClient },
  run: (
    { sync },
    {
      input,
    }: Operation.Ctx<{
      version: number;
      message: { kind: "changes"; events: Sync.Event[] } | { kind: "account-change" };
    }>,
  ) => {
    if (input.version !== sync.version()) return false;
    if (input.message.kind === "changes") {
      sync.apply(input.message.events, input.version);
      return false;
    }
    sync.leave();
    return true;
  },
});

/** One connection, from the applied cursors, until it ends (false) or the account changes (true). */
export const consumeConnection = operation({
  label: "sync.connection",
  depends: {
    sync: syncClient,
    source: eventSource,
    receive: receiveMessage,
    snapshots: snapshotLoader,
    streamMessage: streamMessageSlot.required,
  },
  run: async ({ sync, source, receive, snapshots, streamMessage }, { signal }) => {
    await snapshots.ready();
    const token = sync.capture();
    const cursors = sync.cursors();
    source.connect(
      {
        public: Math.max(0, cursors.publicRevision),
        private:
          cursors.accountId === null
            ? null
            : { accountId: cursors.accountId, revision: Math.max(0, cursors.privateRevision) },
      },
      AbortSignal.any([token.signal, signal]),
    );
    try {
      for (;;) {
        const data = await source.next();
        if (data === undefined) return false;

        let message: { kind: "changes"; events: Sync.Event[] } | { kind: "account-change" };
        try {
          message = streamMessage.parse(JSON.parse(data));
        } catch {
          return false;
        }

        const applied = receive.settle({ input: { version: token.version, message } });
        if (applied.status !== "success") return false;
        if (applied.value) return true;
      }
    } finally {
      source.close();
    }
  },
});

/** Connection refresh checks identity only; the same account keeps its applied event cursors. */
export const refreshAccount = operation({
  label: "sync.refreshAccount",
  depends: {
    sync: syncClient,
    load: loadSnapshot,
    source: snapshotSource,
    snapshots: snapshotLoader,
  },
  run: async ({ sync, load, source, snapshots }, { signal }) => {
    await snapshots.ready();
    const version = sync.version();
    const accountId = await source.account({ signal });
    if (version !== sync.version()) return;
    if (accountId !== sync.cursors().accountId) {
      sync.leave();
      await load.run();
    }
  },
});

/** Connect, read, then reload after an account change or re-check the account; 500 ms apart. */
export const streamChanges = operation({
  label: "sync.listen",
  depends: { consume: consumeConnection, load: loadSnapshot, refresh: refreshAccount },
  run: async ({ consume, load, refresh }, { signal, log, clock }) => {
    while (!signal.aborted) {
      const consumed = await consume.settle();
      if (consumed.status === "failed") log("sync.reconnecting");
      if (signal.aborted) return;

      const loaded =
        consumed.status === "success" && consumed.value
          ? await load.settle()
          : await refresh.settle();
      if (loaded.status === "failed") log("sync.reconnecting");
      await clock.sleep(500, signal);
    }
  },
});

/** The tab's stream: `start` runs it once, until the tab stops. */
export const syncStreaming = resource({
  label: "sync.streaming",
  depends: { listen: streamChanges.controller, stop: tabStop },
  factory: ({ listen, stop }, { defer }) => {
    let running: ReturnType<typeof listen.settle> | undefined;
    defer(async () => {
      const result = await running;
      if (result?.status === "failed") throw result.error;
    });
    return {
      start() {
        running ??= Promise.resolve(listen.settle({ signal: stop }));
      },
    };
  },
});

import { resource } from "@tinker/core";

import { abortReasons } from "~/components/errors";
import { tabStop } from "~/components/sync/client/tab";

/**
 * Who the tab's work belongs to: a version that changes on each account exit, and a signal that
 * stops that account's work. The tab stop signal stops it too, before Core's graceful shutdown
 * waits for it.
 */
export const accountOwner = resource({
  label: "sync.accountOwner",
  depends: { signal: tabStop },
  factory: ({ signal }, { defer }) => {
    let stop = new AbortController();
    let version = 0;

    const cancel = () => stop.abort(abortReasons.closed);
    signal.addEventListener("abort", cancel, { once: true });

    defer(() => {
      signal.removeEventListener("abort", cancel);
      stop.abort(abortReasons.closed);
    });

    return {
      capture: () => ({ version, signal: stop.signal }),
      version: () => version,
      reset: () => {
        stop.abort(abortReasons.changed);
        stop = new AbortController();
        version += 1;
        if (signal.aborted) stop.abort(abortReasons.closed);
      },
    };
  },
});

import { resource } from "@tinker/core";

import { checkAccount, loadSnapshot, syncStreaming } from "~/components/sync/client/events";
import { applyBootstrap, syncClient } from "~/components/sync/client/sync";
import type { SyncPart } from "~/components/sync/part";
import { readSnapshotSlot } from "~/components/sync/slots";

/**
 * The router side of sync: the server render loads the snapshot and dehydrates it; the tab
 * hydrates it, then starts streaming. A real page hide closes the tab's app root.
 */
export const syncRouter = resource({
  label: "sync.router",
  depends: {
    sync: syncClient,
    readSnapshot: readSnapshotSlot.required,
    load: loadSnapshot.controller,
    check: checkAccount.controller,
    apply: applyBootstrap.controller,
    streaming: syncStreaming,
  },
  factory: ({ sync, readSnapshot, load, check, apply, streaming }) => {
    const options: SyncPart.Options = {
      context: { bootstrap: load.run.bind(load), account: check.run.bind(check) },
      dehydrate: sync.snapshot,
      hydrate: async (raw) => {
        const snapshot = readSnapshot.parse(raw);
        apply.run({ input: { snapshot, version: sync.version() } });
        streaming.start();
      },
    };
    return options;
  },
});

import { operation, resource } from "@tinker/core";
import type { Operation } from "@tinker/core";

import { fail, raise } from "~/components/errors";
import { accountOwner } from "~/components/sync/client/owner";
import type { Sync } from "~/components/sync/envelopes";
import { readBatchSlot, readBootstrapSlot, syncStartup } from "~/components/sync/slots";

/**
 * The tab's applied state: the cursor per stream, and the account it belongs to. It keeps only
 * unfinished local writes, including results that arrive before their receipts.
 */
export const syncClient = resource({
  label: "sync.client",
  depends: { owner: accountOwner, records: syncStartup },
  factory: ({ owner, records: appRecords }, { defer, log, clock }) => {
    if (appRecords === undefined) raise("StreamMissing", {});
    const records: Sync.Records = appRecords;
    let accountId: string | null = null;
    const cursors = new Map<string, number>();
    cursors.set("public", -1);
    const local = new Set<string>();
    const results = new Map<string, Sync.Result>();
    const waiters = new Map<string, ReturnType<typeof Promise.withResolvers<Sync.Result>>>();

    defer(() => {
      for (const waiting of waiters.values()) waiting.reject(fail("Cancelled", {}));
      waiters.clear();
      results.clear();
      local.clear();
    });

    const client = {
      capture: owner.capture,
      version: owner.version,
      cursors: () => ({
        accountId,
        publicRevision: cursors.get("public") ?? -1,
        privateRevision: accountId === null ? -1 : (cursors.get(accountId) ?? -1),
      }),
      snapshot: () =>
        records.snapshot(
          cursors.get("public") ?? -1,
          accountId === null ? -1 : (cursors.get(accountId) ?? -1),
        ),
      leave() {
        owner.reset();

        if (accountId !== null) cursors.delete(accountId);
        accountId = null;
        records.resetPrivate();

        for (const waiting of waiters.values()) waiting.reject(fail("Cancelled", {}));
        waiters.clear();
        results.clear();
        local.clear();
      },
      bootstrap(snapshot: Sync.Snapshot, version: number) {
        if (version !== owner.version()) return;

        const nextId = snapshot.private?.stream ?? null;
        if (nextId !== accountId) client.leave();
        if (local.size > 0) return;

        accountId = nextId;
        client.merge(snapshot);
        return owner.version();
      },
      merge(snapshot: Sync.Snapshot) {
        const publicRevision = cursors.get("public") ?? -1;
        records.bootstrapPublic(snapshot.public, publicRevision);
        cursors.set("public", Math.max(publicRevision, snapshot.public.revision));
        if (snapshot.private) {
          const privateRevision = cursors.get(snapshot.private.stream) ?? -1;
          records.bootstrapPrivate(snapshot.private, privateRevision);
          cursors.set(
            snapshot.private.stream,
            Math.max(privateRevision, snapshot.private.revision),
          );
        }
      },
      finish(executionId: string, result: Sync.Result) {
        if (!local.has(executionId)) return;
        results.set(executionId, result);
        waiters.get(executionId)?.resolve(result);
      },
      apply(events: Sync.Event[], version: number) {
        if (version !== owner.version()) return;
        for (const event of events) {
          const previous = cursors.get(event.stream);
          if (previous === undefined || event.revision <= previous) continue;
          if (event.revision !== previous + 1) break;
          if (event.payload.kind === "change") records.change(event.payload.change);
          else client.finish(event.executionId, event.payload.result);
          cursors.set(event.stream, event.revision);
        }
      },
      async wait(executionId: string, version: number, signal: AbortSignal): Promise<Sync.Result> {
        if (version !== owner.version() || signal.aborted) raise("Cancelled", {});
        const completed = results.get(executionId);
        if (completed) return completed;

        const waiting = Promise.withResolvers<Sync.Result>();
        waiters.set(executionId, waiting);
        const stop = () => waiting.reject(fail("Cancelled", {}));
        signal.addEventListener("abort", stop, { once: true });

        try {
          return await waiting.promise;
        } finally {
          signal.removeEventListener("abort", stop);
          waiters.delete(executionId);
        }
      },
      /**
       * Send a write and wait for its result event. A send that throws is retried after 500 ms;
       * a rejected reply fails the write; an account exit or the call's signal cancels it.
       */
      async execute<T>(
        executionId: string,
        request: {
          data: T;
          send: (options: { data: T; signal: AbortSignal }) => Promise<Sync.Reply>;
        },
        callSignal: AbortSignal,
      ): Promise<Sync.Result> {
        const token = owner.capture();
        const signal = AbortSignal.any([token.signal, callSignal]);
        local.add(executionId);
        try {
          for (;;) {
            if (signal.aborted) raise("Cancelled", {});
            let reply: Sync.Reply;
            try {
              reply = await request.send({ data: request.data, signal });
            } catch (error) {
              if (signal.aborted) throw error;
              log("sync.reconnecting");
              await clock.sleep(500, signal);
              continue;
            }
            if (reply.kind === "rejected") raise("WriteRejected", { message: reply.message });

            const result = await client.wait(executionId, token.version, signal);
            if (signal.aborted) raise("Cancelled", {});
            return result;
          }
        } finally {
          local.delete(executionId);
          results.delete(executionId);
        }
      },
    };

    return client;
  },
});

export const applyBootstrap = operation({
  label: "sync.bootstrap",
  depends: { sync: syncClient, read: readBootstrapSlot.required },
  run: (
    { sync, read },
    { input, rawInput, label, raise }: Operation.Ctx<{ snapshot: Sync.Snapshot; version: number }>,
  ) => {
    let value;
    try {
      value = input === undefined ? read.parse(rawInput) : input;
    } catch (cause) {
      return raise("DataValidationFailed", { label, cause });
    }
    return sync.bootstrap(value.snapshot, value.version);
  },
});

export const applyEvents = operation({
  label: "sync.apply",
  depends: { sync: syncClient, read: readBatchSlot.required },
  run: (
    { sync, read },
    { input, rawInput, label, raise }: Operation.Ctx<{ events: Sync.Event[]; version: number }>,
  ) => {
    let value;
    try {
      value = input === undefined ? read.parse(rawInput) : input;
    } catch (cause) {
      return raise("DataValidationFailed", { label, cause });
    }
    return sync.apply(value.events, value.version);
  },
});

export const leaveAccount = operation({
  label: "sync.leave",
  depends: { sync: syncClient },
  run: ({ sync }) => sync.leave(),
});

import { tag } from "@tinker/core";

/** The tab's stop signal: the router entry binds the one that closes its app root. */
export const tabStop = tag<AbortSignal>({ label: "sync.tabStop" });

import { z } from "zod";

/** The app merges this open registry to supply its feature bodies. */
export interface Register {}

export declare namespace Sync {
  type Change = Register extends { change: infer T } ? T : unknown;
  type Result = Register extends { result: infer T } ? T : unknown;
  type Public = Register extends { public: infer T }
    ? { stream: "public"; revision: number } & T
    : { stream: "public"; revision: number };
  type Private = Register extends { private: infer T }
    ? { stream: string; revision: number } & T
    : { stream: string; revision: number };
  type Snapshot = { public: Public; private: Private | null };
  type Payload = { kind: "change"; change: Change } | { kind: "result"; result: Result };
  type Event = { stream: string; revision: number; executionId: string; payload: Payload };
  type Envelope = z.infer<typeof eventEnvelope>;
  type Receipt = { executionId: string };
  type Reply = { kind: "accepted"; executionId: string } | { kind: "rejected"; message: string };
  /** The app's `records`, as the sync client calls them; a revision of -1 means none yet. */
  type Records = {
    resetPrivate(): void;
    bootstrapPublic(saved: Public, after: number): void;
    bootstrapPrivate(saved: Private, after: number): void;
    change(change: Change): void;
    snapshot(publicRevision: number, privateRevision: number): Snapshot;
  };
  /** The router context sync adds: a route's loader or guard calls these. */
  type RouterContext = {
    bootstrap: () => Promise<Snapshot>;
    account: () => Promise<string | null>;
  };
}

export const readExecution = z.object({ executionId: z.uuid() }).strict();
export const readCursor = z.object({ after: z.number().int().min(0) }).strict();

export const readPrivateCursor = z
  .object({ accountId: z.string().min(1), after: z.number().int().min(0) })
  .strict();

export const readRetry = z
  .object({ executionId: z.uuid(), previousExecutionId: z.uuid() })
  .strict();

/** Bodies are opaque here; the app's network readers validate them. */
export const eventEnvelope = z.object({
  stream: z.string(),
  revision: z.number().int().positive(),
  executionId: z.uuid(),
  payload: z.discriminatedUnion("kind", [
    z.object({ kind: z.literal("change"), change: z.unknown() }),
    z.object({ kind: z.literal("result"), result: z.unknown() }),
  ]),
});

export const snapshotEnvelope = z.object({
  public: z.object({ stream: z.literal("public"), revision: z.number().int().min(0) }).loose(),
  private: z
    .object({ stream: z.string(), revision: z.number().int().min(0) })
    .loose()
    .nullable(),
});

export const batchEnvelope = z.object({
  version: z.number().int().min(0),
  events: z.array(eventEnvelope),
});

export const bootstrapEnvelope = z.object({
  version: z.number().int().min(0),
  snapshot: snapshotEnvelope,
});

/** One stream frame as the tab hands it on: the account version it was read under, and its data. */
export const streamInput = z.object({ version: z.number().int().min(0), data: z.string() });

import { createServerFn } from "@tanstack/react-start";
import { setResponseHeader } from "@tanstack/react-start/server";
import { resource } from "@tinker/core";

import { startRequests } from "~/components/requests/index";
import { readResult } from "~/components/requests/index.server";
import type { Sync } from "~/components/sync/envelopes";
import { bootstrapSlot, readAccountSlot } from "~/components/sync/slots";

/** The app's snapshot for this request's account: what a tab loads before it streams. */
export const getBootstrap = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) => {
    setResponseHeader("Cache-Control", "no-store");
    return readResult(
      await context.session.settle(context.session.resolve(bootstrapSlot.required), {
        signal: context.signal,
      }),
    );
  });

/** The account this request signs in as, or null: what a tab checks before it trusts a page. */
export const getAccount = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) => {
    setResponseHeader("Cache-Control", "no-store");
    return readResult(
      await context.session.settle(context.session.resolve(readAccountSlot.required), {
        signal: context.signal,
      }),
    );
  });

/**
 * The tab's network client: the two server functions above. Only scope tests replace it. This file
 * is Start glue (a server function runs only inside Start), so the build proves it, not a test.
 */
export const snapshotSource = resource({
  label: "sync.snapshotSource",
  factory: () => ({
    load: (options: { signal: AbortSignal }): Promise<Sync.Snapshot> => getBootstrap(options),
    account: (options: { signal: AbortSignal }): Promise<string | null> => getAccount(options),
  }),
});

import { operation, resource } from "@tinker/core";
import { z } from "zod";

import { database, drizzleOrm } from "~/components/database/index.server";
import type { Database } from "~/components/database/index.server";
import { raise } from "~/components/errors";
import type { Sync } from "~/components/sync/envelopes";
import { stream, event, execution } from "~/components/sync/schema";

/**
 * Snapshots read a cursor without a row lock. Writers keep their stream row locked
 * until its records and events commit together. The Drizzle module is a lazy dep.
 */
export const eventHistory = resource({
  label: "sync.history",
  depends: { orm: drizzleOrm },
  factory: async ({ orm }) => {
    const { eq, sql } = orm;
    return {
      async read(tx: Database.Transaction, id: string) {
        const [row] = await tx.select().from(stream).where(eq(stream.id, id));
        if (!row) raise("StreamMissing", {});
        return row.revision;
      },
      async lock(tx: Database.Transaction, id: string) {
        await tx.insert(stream).values({ id }).onConflictDoNothing();
        const row = (await tx.select().from(stream).where(eq(stream.id, id)).for("update")).at(0);
        if (!row) raise("StreamMissing", {});
        return row.revision;
      },
      async find(tx: Database.Transaction, id: string, owner: string) {
        const row = (await tx.select().from(execution).where(eq(execution.id, id))).at(0);
        if (row && row.stream !== owner) raise("StreamDenied", {});
        return row;
      },
      async append(
        tx: Database.Transaction,
        owner: string,
        executionId: string,
        payloads: Sync.Payload[],
      ) {
        const row = (
          await tx
            .update(stream)
            .set({ revision: sql`${stream.revision} + ${payloads.length}` })
            .where(eq(stream.id, owner))
            .returning()
        ).at(0);
        if (!row) raise("StreamMissing", {});
        await tx.insert(event).values(
          payloads.map((payload, offset) => ({
            stream: owner,
            revision: row.revision - payloads.length + offset + 1,
            executionId,
            payload,
          })),
        );
        for (const payload of payloads) {
          if (payload.kind === "result") {
            await tx
              .update(execution)
              .set({ result: payload.result })
              .where(eq(execution.id, executionId));
          }
        }
      },
    };
  },
});

